// Builds the static site and places it at the repository root, which GitHub Pages serves.
// Usage (from app-src/): npm run publish
import { execSync } from 'node:child_process';
import { cpSync, existsSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const app = resolve(import.meta.dirname, '..');
const root = resolve(app, '..');
// Everything at the root that is NOT generated by the build
const KEEP = new Set(['.git', '.github', '.gitignore', '.nojekyll', 'app-src', 'README.md', 'firestore.rules', 'setup-guide.html', 'wedding-rsvp-להעלאה']);

const env = { ...process.env, NEXT_TELEMETRY_DISABLED: '1' };
for (const k of Object.keys(env)) if (k.startsWith('NEXT_PUBLIC_') && k !== 'NEXT_PUBLIC_BASE_PATH') delete env[k];

rmSync(join(app, 'out'), { recursive: true, force: true });
execSync('npx next build', { cwd: app, stdio: 'inherit', env });

for (const name of readdirSync(root)) if (!KEEP.has(name)) rmSync(join(root, name), { recursive: true, force: true });
for (const name of readdirSync(join(app, 'out'))) {
  if (name.endsWith('.txt')) continue; // React Server Component payloads, unused on a static host
  cpSync(join(app, 'out', name), join(root, name), { recursive: true });
}
cpSync(join(app, 'firestore.rules'), join(root, 'firestore.rules'));
writeFileSync(join(root, '.nojekyll'), ''); // let GitHub Pages serve the _next/ folder
if (!existsSync(join(root, 'guest.html'))) throw new Error('build output missing guest.html');
console.log('\n✓ Site written to the repository root. Commit and push to publish.');
